146	  .chat-panel {
147	    display: flex;
148	    flex-direction: column;
149	    height: 100%;
150	    font-family: sans-serif;
151	  }
152	  h3 {
153	    font-size: 0.875rem;
154	    font-weight: 600;
155	    margin: 0;
156	    padding: 0.75rem 0.75rem 0.5rem;
157	    text-transform: uppercase;
158	    letter-spacing: 0.05em;
159	    color: #444;
160	    border-bottom: 1px solid #eee;
161	  }
162	  .chat-body {
163	    flex: 1;
164	    display: flex;
165	    flex-direction: column;
166	    overflow: hidden;
167	  }
168	  .error {
169	    color: #c00;
170	    font-size: 0.8rem;
171	    padding: 0.25rem 0.75rem;
172	    margin: 0;
173	  }
174	</style>
